//! Regression model: standard scaling, then ridge regression.
//!
//! This program trains a regression model on train.csv, in which every row holds the feature
//! columns followed by the target as the last column, and then writes one prediction per line for
//! the rows of test_features.csv. All arithmetic is IEEE-754 double precision in a fixed
//! evaluation order, so repeated runs give identical bits.
//!
//! The feature pipeline has 1 stage, applied in order; each stage is marked "replaced" when it
//! overwrites the columns it receives or "appended" when it keeps them and adds its outputs
//! alongside, and after every stage non-finite cells become 0.0 and each row is capped at 512
//! columns. Stage 1 (standard_scaler, replaced) centers each column by its training mean and
//! divides by the standard deviation (1/n convention, floored at 1e-9), clamping the score to
//! [-20, 20].
//!
//! The head (ridge_regression) is ridge regression (Hoerl & Kennard, 1970) on standardized
//! columns with penalty max(0.02*n, 1e-3); the symmetric positive-definite normal equations are
//! solved by a Cholesky factorization and predictions are clipped to [-60, 60]. Seeded stages
//! draw weights from a permuted congruential generator (PCG XSH-RR 64/32; O'Neill, 2014) keyed by
//! the stage seed and the input/output widths, so training is fully deterministic. Missing or
//! malformed CSV cells parse as 0.0 and short rows are padded with zeros to the training width.
//!
//! Build: rustc -O model.rs
//! Usage: ./model train.csv test_features.csv predictions.csv

#![forbid(unsafe_code)]
#![allow(dead_code)]

/// Replace non-finite values with 0.0 in every row.
fn sanitize(x: &[Vec<f64>]) -> Vec<Vec<f64>> {
    x.iter()
        .map(|row| row.iter().map(|v| if v.is_finite() { *v } else { 0.0 }).collect())
        .collect()
}

/// Stage epilogue: optionally keep the inputs, cap width at 512, zero non-finite cells.
fn finish_stage(x: &[Vec<f64>], mut out: Vec<Vec<f64>>, append: bool) -> Vec<Vec<f64>> {
    if append {
        for (i, row) in out.iter_mut().enumerate() {
            let mut merged = x[i].clone();
            merged.append(row);
            *row = merged;
        }
    }
    for row in out.iter_mut() {
        if row.len() > 512 {
            row.truncate(512);
        }
        for v in row.iter_mut() {
            if !v.is_finite() {
                *v = 0.0;
            }
        }
        if row.is_empty() {
            row.push(0.0);
        }
    }
    out
}

/// Per-column mean and standard deviation (1/n convention), floored at 1e-9.
fn std_fit(x: &[Vec<f64>]) -> (Vec<f64>, Vec<f64>) {
    let n = x.len().max(1) as f64;
    let p = x[0].len();
    let mut means = vec![0.0; p];
    let mut scales = vec![1.0; p];
    for j in 0..p {
        let mut s = 0.0;
        for row in x {
            s += row[j];
        }
        means[j] = s / n;
        let mut v = 0.0;
        for row in x {
            let d = row[j] - means[j];
            v += d * d;
        }
        scales[j] = (v / n).sqrt().max(1e-9);
    }
    (means, scales)
}

/// Solve the symmetric positive-definite system A w = b.
///
/// A (flattened row-major, overwritten) is factored in place as L L^T, then a
/// forward and a backward triangular solve produce w. A tiny 1e-6 pivot stands
/// in whenever a diagonal entry falls under 1e-12.
fn cholesky_solve(a: &mut [f64], b: &[f64], p: usize) -> Vec<f64> {
    for i in 0..p {
        for j in 0..(i + 1) {
            let mut s = a[i * p + j];
            for k in 0..j {
                s -= a[i * p + k] * a[j * p + k];
            }
            if i == j {
                a[i * p + j] = if s > 1e-12 { s.sqrt() } else { 1e-6 };
            } else {
                a[i * p + j] = s / a[j * p + j];
            }
        }
    }
    let mut z = vec![0.0; p];
    for i in 0..p {
        let mut s = b[i];
        for k in 0..i {
            s -= a[i * p + k] * z[k];
        }
        z[i] = s / a[i * p + i];
    }
    let mut w = vec![0.0; p];
    for i in (0..p).rev() {
        let mut s = z[i];
        for k in (i + 1)..p {
            s -= a[k * p + i] * w[k];
        }
        w[i] = s / a[i * p + i];
    }
    w
}

struct StandardScaler {
    means: Vec<f64>,
    scales: Vec<f64>,
}

/// This transform centers each column by its training mean and divides by the standard
/// deviation (1/n convention, floored at 1e-9), clamping the score to [-20, 20].
fn standard_scaler_fit(x: &[Vec<f64>]) -> StandardScaler {
    let (means, scales) = std_fit(x);
    StandardScaler { means, scales }
}

fn standard_scaler_apply(state: &StandardScaler, x: &[Vec<f64>], append: bool) -> Vec<Vec<f64>> {
    let out: Vec<Vec<f64>> = x
        .iter()
        .map(|row| {
            row.iter()
                .enumerate()
                .map(|(j, v)| ((v - state.means[j]) / state.scales[j]).clamp(-20.0, 20.0))
                .collect()
        })
        .collect();
    finish_stage(x, out, append)
}

struct RidgeRegression {
    means: Vec<f64>,
    scales: Vec<f64>,
    w: Vec<f64>,
}

/// This head is ridge regression (Hoerl & Kennard, 1970) on standardized columns with penalty
/// max(0.02*n, 1e-3); the symmetric positive-definite normal equations are solved by a Cholesky
/// factorization and predictions are clipped to [-60, 60].
fn ridge_regression_fit(x: &[Vec<f64>], y: &[f64], lambda_frac: f64) -> RidgeRegression {
    let n = x.len().min(y.len());
    let p = x[0].len();
    let (means, scales) = std_fit(x);
    let lam = (lambda_frac * n as f64).max(1e-3);
    let mut y_mean = 0.0;
    for i in 0..n {
        y_mean += y[i];
    }
    y_mean /= n.max(1) as f64;
    let mut ata = vec![0.0; p * p];
    let mut atb = vec![0.0; p];
    let mut xs_row = vec![0.0; p];
    for r in 0..n {
        let row = &x[r];
        for j in 0..p {
            xs_row[j] = ((row[j] - means[j]) / scales[j]).clamp(-20.0, 20.0);
        }
        let yr = y[r] - y_mean;
        for i in 0..p {
            let xi = xs_row[i];
            atb[i] += xi * yr;
            for j in i..p {
                ata[i * p + j] += xi * xs_row[j];
            }
        }
    }
    for i in 0..p {
        ata[i * p + i] += lam;
        for j in 0..i {
            ata[i * p + j] = ata[j * p + i];
        }
    }
    let coeffs = cholesky_solve(&mut ata, &atb, p);
    let mut w = Vec::with_capacity(p + 1);
    w.push(y_mean);
    w.extend(coeffs);
    RidgeRegression { means, scales, w }
}

fn ridge_regression_predict(state: &RidgeRegression, x: &[Vec<f64>]) -> Vec<f64> {
    let p = state.means.len();
    let mut predictions = Vec::new();
    for row in x {
        let mut z = state.w[0];
        for j in 0..p.min(row.len()) {
            let xs = ((row[j] - state.means[j]) / state.scales[j]).clamp(-20.0, 20.0);
            z += state.w[j + 1] * xs;
        }
        predictions.push(z.clamp(-60.0, 60.0));
    }
    predictions
}

/// Feature stages applied in order, then the ridge_regression head.
struct Model {
    stage1: StandardScaler,
    head: RidgeRegression,
}

impl Model {
    /// Fit every stage in order on the training rows.
    fn fit(x: &[Vec<f64>], y: &[f64]) -> Model {
        if x.is_empty() || y.len() < x.len() {
            eprintln!("training data is empty or target is short");
            std::process::exit(2);
        }
        let x = sanitize(x);
        let stage1 = standard_scaler_fit(&x);
        let x = standard_scaler_apply(&stage1, &x, false);
        let head = ridge_regression_fit(&x, y, 0.02);
        Model { stage1, head }
    }

    /// Apply the fitted stages, then the regression head.
    fn predict(&self, x: &[Vec<f64>]) -> Vec<f64> {
        let x = sanitize(x);
        let x = standard_scaler_apply(&self.stage1, &x, false);
        ridge_regression_predict(&self.head, &x)
    }

    /// Coefficient of determination R^2 of predict against y.
    fn score(&self, x: &[Vec<f64>], y: &[f64]) -> f64 {
        let predictions = self.predict(x);
        let n = y.len().min(predictions.len());
        if n == 0 {
            return 0.0;
        }
        let mut mean = 0.0;
        for i in 0..n {
            mean += y[i];
        }
        mean /= n as f64;
        let mut ss_res = 0.0;
        let mut ss_tot = 0.0;
        for i in 0..n {
            let d = y[i] - predictions[i];
            ss_res += d * d;
            let t = y[i] - mean;
            ss_tot += t * t;
        }
        if ss_tot <= 0.0 {
            return 0.0;
        }
        1.0 - ss_res / ss_tot
    }
}

/// Parse one CSV cell; blank, malformed, or non-finite cells become 0.0.
fn parse_cell(cell: &str) -> f64 {
    let text = cell.trim();
    if text.is_empty() || text.contains('_') {
        return 0.0;
    }
    match text.parse::<f64>() {
        Ok(value) => {
            if value.is_finite() {
                value
            } else {
                0.0
            }
        }
        Err(_) => 0.0,
    }
}

fn looks_numeric(cell: &str) -> bool {
    let text = cell.trim();
    text.is_empty() || (!text.contains('_') && text.parse::<f64>().is_ok())
}

/// Read CSV rows of floats, skipping blank lines and one header line if present.
fn read_csv(path: &str) -> Vec<Vec<f64>> {
    let text = match std::fs::read_to_string(path) {
        Ok(text) => text,
        Err(err) => {
            eprintln!("cannot read {}: {}", path, err);
            std::process::exit(2);
        }
    };
    let mut records: Vec<Vec<&str>> = Vec::new();
    for line in text.lines() {
        let cells: Vec<&str> = line.split(',').collect();
        if cells.iter().all(|cell| cell.trim().is_empty()) {
            continue;
        }
        records.push(cells);
    }
    if !records.is_empty() && !records[0].iter().all(|cell| looks_numeric(cell)) {
        records.remove(0);
    }
    records
        .iter()
        .map(|cells| cells.iter().map(|cell| parse_cell(cell)).collect())
        .collect()
}

/// Pad short rows with 0.0 (and trim long ones) to the training feature width.
fn pad(mut row: Vec<f64>, width: usize) -> Vec<f64> {
    while row.len() < width {
        row.push(0.0);
    }
    row.truncate(width);
    row
}

/// One shortest round-trip decimal per line (matches Python's repr()).
fn write_predictions(path: &str, predictions: &[f64]) {
    let mut out = String::new();
    for value in predictions {
        out.push_str(&format!("{:?}\n", value));
    }
    if let Err(err) = std::fs::write(path, out) {
        eprintln!("cannot write {}: {}", path, err);
        std::process::exit(2);
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 {
        eprintln!("usage: model train.csv test_features.csv predictions.csv");
        std::process::exit(2);
    }
    let train_rows = read_csv(&args[1]);
    if train_rows.is_empty() {
        eprintln!("training data is empty");
        std::process::exit(2);
    }
    let y_train: Vec<f64> = train_rows.iter().map(|row| row[row.len() - 1]).collect();
    let features: Vec<Vec<f64>> = train_rows.iter().map(|row| row[..row.len() - 1].to_vec()).collect();
    let mut width = 0usize;
    for row in &features {
        if row.len() > width {
            width = row.len();
        }
    }
    let mut x_train: Vec<Vec<f64>> = Vec::new();
    for row in features {
        x_train.push(pad(row, width));
    }
    let mut x_test: Vec<Vec<f64>> = Vec::new();
    for row in read_csv(&args[2]) {
        x_test.push(pad(row, width));
    }
    let model = Model::fit(&x_train, &y_train);
    let predictions = model.predict(&x_test);
    write_predictions(&args[3], &predictions);
}

"""Regression model: standard scaling, then ridge regression.

This program trains a regression model on train.csv, in which every row holds the feature
columns followed by the target as the last column, and then writes one prediction per line for
the rows of test_features.csv. All arithmetic is IEEE-754 double precision in a fixed evaluation
order, so repeated runs give identical bits.

The feature pipeline has 1 stage, applied in order; each stage is marked "replaced" when it
overwrites the columns it receives or "appended" when it keeps them and adds its outputs
alongside, and after every stage non-finite cells become 0.0 and each row is capped at 512
columns. Stage 1 (standard_scaler, replaced) centers each column by its training mean and
divides by the standard deviation (1/n convention, floored at 1e-9), clamping the score to [-20,
20].

The head (ridge_regression) is ridge regression (Hoerl & Kennard, 1970) on standardized columns
with penalty max(0.02*n, 1e-3); the symmetric positive-definite normal equations are solved by a
Cholesky factorization and predictions are clipped to [-60, 60]. Seeded stages draw weights from
a permuted congruential generator (PCG XSH-RR 64/32; O'Neill, 2014) keyed by the stage seed and
the input/output widths, so training is fully deterministic. Missing or malformed CSV cells
parse as 0.0 and short rows are padded with zeros to the training width.

Usage: python3 model.py train.csv test_features.csv predictions.csv
"""


import csv
import math
import sys


def _clamp(value, lo, hi):
    """Clamp value to [lo, hi]; NaN passes through (same branch order as the mirror)."""
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value


def _sanitize(x):
    """Replace non-finite values with 0.0 in every row."""
    return [[v if math.isfinite(v) else 0.0 for v in row] for row in x]


def _finish_stage(x, out, append):
    """Stage epilogue: optionally keep the inputs, cap width at 512, zero non-finite cells."""
    if append:
        out = [x[i] + out[i] for i in range(len(out))]
    result = []
    for row in out:
        if len(row) > 512:
            row = row[:512]
        row = [v if math.isfinite(v) else 0.0 for v in row]
        if not row:
            row = [0.0]
        result.append(row)
    return result


def _std_fit(x):
    """Per-column mean and standard deviation (1/n convention), floored at 1e-9."""
    n = max(len(x), 1)
    p = len(x[0])
    means = [0.0] * p
    scales = [1.0] * p
    for j in range(p):
        s = 0.0
        for row in x:
            s += row[j]
        means[j] = s / n
        v = 0.0
        for row in x:
            d = row[j] - means[j]
            v += d * d
        scales[j] = max(math.sqrt(v / n), 1e-9)
    return means, scales


def _cholesky_solve(a, b, p):
    """Solve the symmetric positive-definite system A w = b.

    A (flattened row-major, overwritten) is factored in place as L L^T, then a
    forward and a backward triangular solve produce w. A tiny 1e-6 pivot stands
    in whenever a diagonal entry falls under 1e-12."""
    for i in range(p):
        for j in range(i + 1):
            s = a[i * p + j]
            for k in range(j):
                s -= a[i * p + k] * a[j * p + k]
            if i == j:
                a[i * p + j] = math.sqrt(s) if s > 1e-12 else 1e-6
            else:
                a[i * p + j] = s / a[j * p + j]
    z = [0.0] * p
    for i in range(p):
        s = b[i]
        for k in range(i):
            s -= a[i * p + k] * z[k]
        z[i] = s / a[i * p + i]
    w = [0.0] * p
    for i in range(p - 1, -1, -1):
        s = z[i]
        for k in range(i + 1, p):
            s -= a[k * p + i] * w[k]
        w[i] = s / a[i * p + i]
    return w


def standard_scaler_fit(x):
    """This transform centers each column by its training mean and divides by the standard
    deviation (1/n convention, floored at 1e-9), clamping the score to [-20, 20].
    """
    return _std_fit(x)


def standard_scaler_apply(state, x, append):
    means, scales = state
    out = [[_clamp((v - means[j]) / scales[j], -20.0, 20.0) for j, v in enumerate(row)] for row in x]
    return _finish_stage(x, out, append)


def ridge_regression_fit(x, y, lambda_frac):
    """This head is ridge regression (Hoerl & Kennard, 1970) on standardized columns with penalty
    max(0.02*n, 1e-3); the symmetric positive-definite normal equations are solved by a Cholesky
    factorization and predictions are clipped to [-60, 60].
    """
    n = min(len(x), len(y))
    p = len(x[0])
    means, scales = _std_fit(x)
    lam = max(lambda_frac * n, 1e-3)
    y_mean = 0.0
    for i in range(n):
        y_mean += y[i]
    y_mean /= max(n, 1)
    ata = [0.0] * (p * p)
    atb = [0.0] * p
    xs_row = [0.0] * p
    for r in range(n):
        row = x[r]
        for j in range(p):
            xs_row[j] = _clamp((row[j] - means[j]) / scales[j], -20.0, 20.0)
        yr = y[r] - y_mean
        for i in range(p):
            xi = xs_row[i]
            atb[i] += xi * yr
            for j in range(i, p):
                ata[i * p + j] += xi * xs_row[j]
    for i in range(p):
        ata[i * p + i] += lam
        for j in range(i):
            ata[i * p + j] = ata[j * p + i]
    w = [y_mean] + _cholesky_solve(ata, atb, p)
    return (means, scales, w)


def ridge_regression_predict(state, x):
    means, scales, w = state
    p = len(means)
    predictions = []
    for row in x:
        z = w[0]
        for j in range(min(p, len(row))):
            xs = _clamp((row[j] - means[j]) / scales[j], -20.0, 20.0)
            z += w[j + 1] * xs
        predictions.append(_clamp(z, -60.0, 60.0))
    return predictions


class Model:
    """Feature stages applied in order, then the ridge_regression head."""

    def fit(self, x_rows: list, y: list) -> "Model":
        """Fit every stage in order on the training rows."""
        if not x_rows or len(y) < len(x_rows):
            raise SystemExit("training data is empty or target is short")
        x = _sanitize(x_rows)
        self.stage1 = standard_scaler_fit(x)
        x = standard_scaler_apply(self.stage1, x, False)
        self.head = ridge_regression_fit(x, y, 0.02)
        return self

    def predict(self, x_rows: list) -> list:
        """Apply the fitted stages, then the regression head."""
        x = _sanitize(x_rows)
        x = standard_scaler_apply(self.stage1, x, False)
        return ridge_regression_predict(self.head, x)

    def score(self, x_rows: list, y: list) -> float:
        """Coefficient of determination R^2 of predict(x_rows) against y."""
        predictions = self.predict(x_rows)
        n = min(len(y), len(predictions))
        if n == 0:
            return 0.0
        mean = 0.0
        for i in range(n):
            mean += y[i]
        mean /= n
        ss_res = 0.0
        ss_tot = 0.0
        for i in range(n):
            d = y[i] - predictions[i]
            ss_res += d * d
            t = y[i] - mean
            ss_tot += t * t
        if ss_tot <= 0.0:
            return 0.0
        return 1.0 - ss_res / ss_tot


def _parse_cell(cell):
    """Parse one CSV cell; blank, malformed, or non-finite cells become 0.0."""
    text = cell.strip()
    if not text or "_" in text:
        return 0.0
    try:
        value = float(text)
    except ValueError:
        return 0.0
    return value if math.isfinite(value) else 0.0


def _looks_numeric(cell):
    text = cell.strip()
    if not text:
        return True
    if "_" in text:
        return False
    try:
        float(text)
    except ValueError:
        return False
    return True


def _read_csv(path):
    """Read CSV rows of floats, skipping blank lines and one header line if present."""
    records = []
    with open(path, newline="") as handle:
        for record in csv.reader(handle):
            if not record or all(not cell.strip() for cell in record):
                continue
            records.append(record)
    if records and not all(_looks_numeric(cell) for cell in records[0]):
        records = records[1:]
    return [[_parse_cell(cell) for cell in record] for record in records]


def _pad(row, width):
    """Pad short rows with 0.0 (and trim long ones) to the training feature width."""
    if len(row) < width:
        return row + [0.0] * (width - len(row))
    return row[:width]


def _write_predictions(path, predictions):
    """One repr() per line: the shortest decimal that parses back to the same float."""
    with open(path, "w") as handle:
        for value in predictions:
            handle.write(repr(value) + "\n")


def main(argv):
    if len(argv) != 3:
        raise SystemExit("usage: python3 model.py train.csv test_features.csv predictions.csv")
    train_rows = _read_csv(argv[0])
    if not train_rows:
        raise SystemExit("training data is empty")
    y_train = [row[-1] for row in train_rows]
    features = [row[:-1] for row in train_rows]
    width = 0
    for row in features:
        if len(row) > width:
            width = len(row)
    x_train = [_pad(row, width) for row in features]
    x_test = [_pad(row, width) for row in _read_csv(argv[1])]
    model = Model()
    model.fit(x_train, y_train)
    _write_predictions(argv[2], model.predict(x_test))


if __name__ == "__main__":
    main(sys.argv[1:])

// Standalone regression model — self-contained, depends only on the C++
// standard library, and accepts all data through its C ABI.
//   Build: g++ -O2 -std=c++17 -ffp-contract=off -fno-fast-math -c model.cpp
//
// All arithmetic uses IEEE-754 double precision in a fixed evaluation order, so
// repeated runs on the same input produce identical results. Build without
// fused-multiply-add contraction (-ffp-contract=off) to keep each multiply and
// add separately rounded.
#include <algorithm>
#include <cmath>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <limits>
#include <stdexcept>
#include <utility>
#include <vector>

// Clamp to [lo, hi] with a fixed branch order; a NaN input passes through.
static double clamp_range(double x, double lo, double hi) {
    if (x < lo) x = lo;
    if (x > hi) x = hi;
    return x;
}

// Larger of two values, ignoring NaN.
static double max_num(double a, double b) {
    if (std::isnan(a)) return b;
    if (std::isnan(b)) return a;
    if (a < b) return b;
    return a;
}

// IEEE-754 total order, so sorts and score-ranking are deterministic (matches the
// reference tie/sign handling). Unused by pipelines with no ordering stage.
[[maybe_unused]] static bool total_less(double a, double b) {
    std::uint64_t ua;
    std::uint64_t ub;
    std::memcpy(&ua, &a, sizeof(double));
    std::memcpy(&ub, &b, sizeof(double));
    std::int64_t la = static_cast<std::int64_t>(ua);
    std::int64_t lb = static_cast<std::int64_t>(ub);
    la ^= static_cast<std::int64_t>(static_cast<std::uint64_t>(la >> 63) >> 1);
    lb ^= static_cast<std::int64_t>(static_cast<std::uint64_t>(lb >> 63) >> 1);
    return la < lb;
}

// Replace non-finite values with 0.0 in every row.
static std::vector<std::vector<double>> sanitize(const std::vector<std::vector<double>>& x) {
    std::vector<std::vector<double>> out;
    out.reserve(x.size());
    for (const auto& row : x) {
        std::vector<double> r;
        r.reserve(row.size());
        for (double v : row) r.push_back(std::isfinite(v) ? v : 0.0);
        out.push_back(std::move(r));
    }
    return out;
}

// Stage epilogue: optionally keep the inputs, cap width at 512, zero non-finite cells.
static std::vector<std::vector<double>> finish_stage(const std::vector<std::vector<double>>& x, std::vector<std::vector<double>> out, bool append) {
    if (append) {
        for (std::size_t i = 0; i < out.size(); ++i) {
            std::vector<double> merged = x[i];
            merged.insert(merged.end(), out[i].begin(), out[i].end());
            out[i] = std::move(merged);
        }
    }
    for (auto& row : out) {
        if (row.size() > 512) row.resize(512);
        for (double& v : row) {
            if (!std::isfinite(v)) v = 0.0;
        }
        if (row.empty()) row.push_back(0.0);
    }
    return out;
}

// Per-column mean and standard deviation (1/n convention), floored at 1e-9.
static void std_fit(const std::vector<std::vector<double>>& x, std::vector<double>& means, std::vector<double>& scales) {
    double n = static_cast<double>(std::max<std::size_t>(x.size(), 1));
    std::size_t p = x[0].size();
    means.assign(p, 0.0);
    scales.assign(p, 1.0);
    for (std::size_t j = 0; j < p; ++j) {
        double s = 0.0;
        for (const auto& row : x) s += row[j];
        means[j] = s / n;
        double v = 0.0;
        for (const auto& row : x) {
            double d = row[j] - means[j];
            v += d * d;
        }
        scales[j] = max_num(std::sqrt(v / n), 1e-9);
    }
}

// Solve the symmetric positive-definite system A w = b (A row-major, overwritten
// in place as L L^T, then forward and backward triangular solves).
static std::vector<double> cholesky_solve(std::vector<double>& a, const std::vector<double>& b, std::size_t p) {
    for (std::size_t i = 0; i < p; ++i) {
        for (std::size_t j = 0; j < i + 1; ++j) {
            double s = a[i * p + j];
            for (std::size_t k = 0; k < j; ++k) s -= a[i * p + k] * a[j * p + k];
            if (i == j) {
                a[i * p + j] = (s > 1e-12) ? std::sqrt(s) : 1e-6;
            } else {
                a[i * p + j] = s / a[j * p + j];
            }
        }
    }
    std::vector<double> z(p, 0.0);
    for (std::size_t i = 0; i < p; ++i) {
        double s = b[i];
        for (std::size_t k = 0; k < i; ++k) s -= a[i * p + k] * z[k];
        z[i] = s / a[i * p + i];
    }
    std::vector<double> w(p, 0.0);
    for (std::size_t ii = 0; ii < p; ++ii) {
        std::size_t i = p - 1 - ii;
        double s = z[i];
        for (std::size_t k = i + 1; k < p; ++k) s -= a[k * p + i] * w[k];
        w[i] = s / a[i * p + i];
    }
    return w;
}

struct StandardScaler {
    std::vector<double> means;
    std::vector<double> scales;
};

// Centers each column by its training mean and divides by its standard deviation.
static StandardScaler standard_scaler_fit(const std::vector<std::vector<double>>& x) {
    StandardScaler state;
    std_fit(x, state.means, state.scales);
    return state;
}

static std::vector<std::vector<double>> standard_scaler_apply(const StandardScaler& state, const std::vector<std::vector<double>>& x, bool append) {
    std::vector<std::vector<double>> out;
    out.reserve(x.size());
    for (const auto& row : x) {
        std::vector<double> r;
        r.reserve(row.size());
        for (std::size_t j = 0; j < row.size(); ++j) {
            r.push_back(clamp_range((row[j] - state.means[j]) / state.scales[j], -20.0, 20.0));
        }
        out.push_back(std::move(r));
    }
    return finish_stage(x, std::move(out), append);
}

struct RidgeRegression {
    std::vector<double> means;
    std::vector<double> scales;
    std::vector<double> w;
};

// Ridge regression on standardized features via the Cholesky normal equations.
static RidgeRegression ridge_regression_fit(const std::vector<std::vector<double>>& x, const std::vector<double>& y, double lambda_frac) {
    std::size_t n = std::min(x.size(), y.size());
    std::size_t p = x[0].size();
    std::vector<double> means;
    std::vector<double> scales;
    std_fit(x, means, scales);
    double lam = max_num(lambda_frac * static_cast<double>(n), 1e-3);
    double y_mean = 0.0;
    for (std::size_t i = 0; i < n; ++i) y_mean += y[i];
    y_mean /= static_cast<double>(std::max<std::size_t>(n, 1));
    std::vector<double> ata(p * p, 0.0);
    std::vector<double> atb(p, 0.0);
    std::vector<double> xs_row(p, 0.0);
    for (std::size_t r = 0; r < n; ++r) {
        const auto& row = x[r];
        for (std::size_t j = 0; j < p; ++j) {
            xs_row[j] = clamp_range((row[j] - means[j]) / scales[j], -20.0, 20.0);
        }
        double yr = y[r] - y_mean;
        for (std::size_t i = 0; i < p; ++i) {
            double xi = xs_row[i];
            atb[i] += xi * yr;
            for (std::size_t j = i; j < p; ++j) {
                ata[i * p + j] += xi * xs_row[j];
            }
        }
    }
    for (std::size_t i = 0; i < p; ++i) {
        ata[i * p + i] += lam;
        for (std::size_t j = 0; j < i; ++j) {
            ata[i * p + j] = ata[j * p + i];
        }
    }
    std::vector<double> coeffs = cholesky_solve(ata, atb, p);
    std::vector<double> w;
    w.reserve(p + 1);
    w.push_back(y_mean);
    for (double c : coeffs) w.push_back(c);
    RidgeRegression state;
    state.means = std::move(means);
    state.scales = std::move(scales);
    state.w = std::move(w);
    return state;
}

static std::vector<double> ridge_regression_predict(const RidgeRegression& state, const std::vector<std::vector<double>>& x) {
    std::size_t p = state.means.size();
    std::vector<double> predictions;
    predictions.reserve(x.size());
    for (const auto& row : x) {
        double z = state.w[0];
        std::size_t lim = std::min(p, row.size());
        for (std::size_t j = 0; j < lim; ++j) {
            double xs = clamp_range((row[j] - state.means[j]) / state.scales[j], -20.0, 20.0);
            z += state.w[j + 1] * xs;
        }
        predictions.push_back(clamp_range(z, -60.0, 60.0));
    }
    return predictions;
}

// Feature stages applied in order, then the ridge regression head.
struct Model {
    StandardScaler stage1;
    RidgeRegression head;

    static Model fit(const std::vector<std::vector<double>>& x_in, const std::vector<double>& y);
    std::vector<double> predict(const std::vector<std::vector<double>>& x_in) const;
};

Model Model::fit(const std::vector<std::vector<double>>& x_in, const std::vector<double>& y) {
    if (x_in.empty() || y.size() < x_in.size()) {
        throw std::invalid_argument("training data is empty or target is short");
    }
    std::vector<std::vector<double>> x = sanitize(x_in);
    auto stage1 = standard_scaler_fit(x);
    x = standard_scaler_apply(stage1, x, false);
    RidgeRegression head = ridge_regression_fit(x, y, 0.02);
    Model m;
    m.stage1 = std::move(stage1);
    m.head = std::move(head);
    return m;
}

std::vector<double> Model::predict(const std::vector<std::vector<double>>& x_in) const {
    std::vector<std::vector<double>> x = sanitize(x_in);
    x = standard_scaler_apply(stage1, x, false);
    return ridge_regression_predict(head, x);
}

// ---- caller-owned C ABI ----------------------------------------------------

extern "C" {

struct model_handle {
    Model model;
    std::size_t width;

    model_handle(Model&& fitted, std::size_t fitted_width)
        : model(std::move(fitted)), width(fitted_width) {}
};

std::uint32_t model_abi_version(void) noexcept {
    return 1U;
}

std::size_t model_workspace_bytes(const model_handle*, std::size_t) noexcept {
    return 0U;
}

int model_fit_numeric(
    const double* values,
    std::size_t values_len,
    std::size_t rows,
    std::size_t columns,
    const double* targets,
    std::size_t target_len,
    model_handle** out
) noexcept {
    if (out == nullptr) return 1;
    *out = nullptr;
    if (values == nullptr || targets == nullptr || rows == 0U || columns == 0U) return 1;
    if (target_len != rows) return 1;
    if (rows > std::numeric_limits<std::size_t>::max() / columns) return 1;
    if (values_len < rows * columns) return 1;
    try {
        std::vector<std::vector<double>> x;
        x.reserve(rows);
        std::vector<double> y;
        y.reserve(rows);
        for (std::size_t row = 0; row < rows; ++row) {
            std::vector<double> cells;
            cells.reserve(columns);
            for (std::size_t column = 0; column < columns; ++column) {
                cells.push_back(values[row * columns + column]);
            }
            if (!std::isfinite(targets[row])) return 1;
            x.push_back(std::move(cells));
            y.push_back(targets[row]);
        }
        Model fitted = Model::fit(x, y);
        *out = new model_handle(std::move(fitted), columns);
        return 0;
    } catch (...) {
        return 2;
    }
}

int model_predict_numeric_batch(
    const model_handle* handle,
    const double* values,
    std::size_t values_len,
    std::size_t rows,
    std::size_t columns,
    void* workspace,
    std::size_t workspace_bytes,
    double* out,
    std::size_t out_len
) noexcept {
    (void)workspace;
    (void)workspace_bytes;
    if (handle == nullptr || columns == 0U || columns != handle->width) return 1;
    if (rows == 0U) return values_len == 0U ? 0 : 1;
    if (rows > std::numeric_limits<std::size_t>::max() / columns) return 1;
    if (values == nullptr || values_len < rows * columns || out == nullptr || out_len < rows) return 1;
    try {
        std::vector<std::vector<double>> x;
        x.reserve(rows);
        for (std::size_t row = 0; row < rows; ++row) {
            std::vector<double> cells;
            cells.reserve(columns);
            for (std::size_t column = 0; column < columns; ++column) {
                cells.push_back(values[row * columns + column]);
            }
            x.push_back(std::move(cells));
        }
        std::vector<double> predictions = handle->model.predict(x);
        if (predictions.size() != rows) return 2;
        for (std::size_t row = 0; row < rows; ++row) out[row] = predictions[row];
        return 0;
    } catch (...) {
        return 2;
    }
}

void model_unload(model_handle* handle) noexcept {
    delete handle;
}

}  // extern "C"

// Standalone regression model. All input and output crosses typed numeric boundaries.
'use strict';

